import {
  IsUUID,
  IsNotEmpty,
  IsString,
  IsOptional,
  IsIn,
  IsArray,
} from 'class-validator';
import { MessageType } from '@prisma/client';

// SYSTEM messages are generated by the server only (group created, members added)
const CLIENT_MESSAGE_TYPES = [MessageType.TEXT, MessageType.IMAGE, MessageType.FILE];

export class SendMessageDto {
  @IsUUID('4', { message: 'معرف المحادثة غير صالح' })
  @IsNotEmpty({ message: 'معرف المحادثة مطلوب' })
  conversationId: string;

  @IsOptional()
  @IsString()
  content?: string;

  @IsOptional()
  @IsIn(CLIENT_MESSAGE_TYPES, { message: 'نوع الرسالة غير صالح' })
  type?: MessageType = MessageType.TEXT;

  @IsOptional()
  @IsArray()
  @IsString({ each: true })
  attachmentUrls?: string[] = [];

  @IsOptional()
  @IsUUID('4', { message: 'معرف الرسالة المقتبسة غير صالح' })
  replyToId?: string;
}
